const assert = require('assert');
const jsdom = require('jsdom');
const fs = require('fs');
const TEMPLATE_FILE = fs.readFileSync(__dirname + '/../../../../report/html/templates.html', 'utf8');

// Sample data to simulate the report rendering
const sampleResults = {
  reportCategories: [
    {
      id: 'performance',
      title: 'Performance',
      auditRefs: [
        {
          id: 'redirects',
          result: {
            title: 'Avoid multiple page redirects',
            description: 'Redirects can slow down your page load.',
            score: 0,
            scoreDisplayMode: 'numeric',
            details: {
              type: 'opportunity',
              overallSavingsMs: 1550,
            },
          },
        },
      ],
    },
  ],
};

// Simulate rendering the report
const document = jsdom.jsdom(TEMPLATE_FILE);
const dom = new DOM(document);
const detailsRenderer = new DetailsRenderer(dom);
const categoryRenderer = new CategoryRenderer(dom, detailsRenderer);
const renderer = new ReportRenderer(dom, categoryRenderer);

// Render the report
const container = renderer._dom._document.body;
const output = renderer.renderReport(sampleResults, container);

// Check if the 'Avoid multiple page redirects' is rendered correctly
const opportunity = output.querySelector('.lh-audit--opportunity');
assert.ok(opportunity, 'Opportunity section is rendered');
assert.ok(opportunity.textContent.includes('Avoid multiple page redirects'), 'Redirects opportunity is present');
